macro_rules! deps {
    () => {
        Inner!();
        Match!();
        Span!();
        DFA!();
    };
}

macro_rules! NFA {
    () => {
        deps!();
        # [doc = " A byte oriented Thompson non-deterministic finite automaton (NFA)."] # [doc = ""] # [doc = " A Thompson NFA is a finite state machine that permits unconditional epsilon"] # [doc = " transitions, but guarantees that there exists at most one non-epsilon"] # [doc = " transition for each element in the alphabet for each state."] # [doc = ""] # [doc = " An NFA may be used directly for searching, for analysis or to build"] # [doc = " a deterministic finite automaton (DFA)."] # [doc = ""] # [doc = " # Cheap clones"] # [doc = ""] # [doc = " Since an NFA is a core data type in this crate that many other regex"] # [doc = " engines are based on top of, it is convenient to give ownership of an NFA"] # [doc = " to said regex engines. Because of this, an NFA uses reference counting"] # [doc = " internally. Therefore, it is cheap to clone and it is encouraged to do so."] # [doc = ""] # [doc = " # Capabilities"] # [doc = ""] # [doc = " Using an NFA for searching via the"] # [doc = " [`PikeVM`](crate::nfa::thompson::pikevm::PikeVM) provides the most amount"] # [doc = " of \"power\" of any regex engine in this crate. Namely, it supports the"] # [doc = " following in all cases:"] # [doc = ""] # [doc = " 1. Detection of a match."] # [doc = " 2. Location of a match, including both the start and end offset, in a"] # [doc = " single pass of the haystack."] # [doc = " 3. Location of matching capturing groups."] # [doc = " 4. Handles multiple patterns, including (1)-(3) when multiple patterns are"] # [doc = " present."] # [doc = ""] # [doc = " # Capturing Groups"] # [doc = ""] # [doc = " Groups refer to parenthesized expressions inside a regex pattern. They look"] # [doc = " like this, where `exp` is an arbitrary regex:"] # [doc = ""] # [doc = " * `(exp)` - An unnamed capturing group."] # [doc = " * `(?P<name>exp)` or `(?<name>exp)` - A named capturing group."] # [doc = " * `(?:exp)` - A non-capturing group."] # [doc = " * `(?i:exp)` - A non-capturing group that sets flags."] # [doc = ""] # [doc = " Only the first two forms are said to be _capturing_. Capturing"] # [doc = " means that the last position at which they match is reportable. The"] # [doc = " [`Captures`](crate::util::captures::Captures) type provides convenient"] # [doc = " access to the match positions of capturing groups, which includes looking"] # [doc = " up capturing groups by their name."] # [doc = ""] # [doc = " # Byte oriented"] # [doc = ""] # [doc = " This NFA is byte oriented, which means that all of its transitions are"] # [doc = " defined on bytes. In other words, the alphabet of an NFA consists of the"] # [doc = " 256 different byte values."] # [doc = ""] # [doc = " While DFAs nearly demand that they be byte oriented for performance"] # [doc = " reasons, an NFA could conceivably be *Unicode codepoint* oriented. Indeed,"] # [doc = " a previous version of this NFA supported both byte and codepoint oriented"] # [doc = " modes. A codepoint oriented mode can work because an NFA fundamentally uses"] # [doc = " a sparse representation of transitions, which works well with the large"] # [doc = " sparse space of Unicode codepoints."] # [doc = ""] # [doc = " Nevertheless, this NFA is only byte oriented. This choice is primarily"] # [doc = " driven by implementation simplicity, and also in part memory usage. In"] # [doc = " practice, performance between the two is roughly comparable. However,"] # [doc = " building a DFA (including a hybrid DFA) really wants a byte oriented NFA."] # [doc = " So if we do have a codepoint oriented NFA, then we also need to generate"] # [doc = " byte oriented NFA in order to build an hybrid NFA/DFA. Thus, by only"] # [doc = " generating byte oriented NFAs, we can produce one less NFA. In other words,"] # [doc = " if we made our NFA codepoint oriented, we'd need to *also* make it support"] # [doc = " a byte oriented mode, which is more complicated. But a byte oriented mode"] # [doc = " can support everything."] # [doc = ""] # [doc = " # Differences with DFAs"] # [doc = ""] # [doc = " At the theoretical level, the precise difference between an NFA and a DFA"] # [doc = " is that, in a DFA, for every state, an input symbol unambiguously refers"] # [doc = " to a single transition _and_ that an input symbol is required for each"] # [doc = " transition. At a practical level, this permits DFA implementations to be"] # [doc = " implemented at their core with a small constant number of CPU instructions"] # [doc = " for each byte of input searched. In practice, this makes them quite a bit"] # [doc = " faster than NFAs _in general_. Namely, in order to execute a search for any"] # [doc = " Thompson NFA, one needs to keep track of a _set_ of states, and execute"] # [doc = " the possible transitions on all of those states for each input symbol."] # [doc = " Overall, this results in much more overhead. To a first approximation, one"] # [doc = " can expect DFA searches to be about an order of magnitude faster."] # [doc = ""] # [doc = " So why use an NFA at all? The main advantage of an NFA is that it takes"] # [doc = " linear time (in the size of the pattern string after repetitions have been"] # [doc = " expanded) to build and linear memory usage. A DFA, on the other hand, may"] # [doc = " take exponential time and/or space to build. Even in non-pathological"] # [doc = " cases, DFAs often take quite a bit more memory than their NFA counterparts,"] # [doc = " _especially_ if large Unicode character classes are involved. Of course,"] # [doc = " an NFA also provides additional capabilities. For example, it can match"] # [doc = " Unicode word boundaries on non-ASCII text and resolve the positions of"] # [doc = " capturing groups."] # [doc = ""] # [doc = " Note that a [`hybrid::regex::Regex`](crate::hybrid::regex::Regex) strikes a"] # [doc = " good balance between an NFA and a DFA. It avoids the exponential build time"] # [doc = " of a DFA while maintaining its fast search time. The downside of a hybrid"] # [doc = " NFA/DFA is that in some cases it can be slower at search time than the NFA."] # [doc = " (It also has less functionality than a pure NFA. It cannot handle Unicode"] # [doc = " word boundaries on non-ASCII text and cannot resolve capturing groups.)"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This shows how to build an NFA with the default configuration and execute a"] # [doc = " search using the Pike VM."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{nfa::thompson::pikevm::PikeVM, Match};"] # [doc = ""] # [doc = " let re = PikeVM::new(r\"foo[0-9]+\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = " let mut caps = re.create_captures();"] # [doc = ""] # [doc = " let expected = Some(Match::must(0, 0..8));"] # [doc = " re.captures(&mut cache, b\"foo12345\", &mut caps);"] # [doc = " assert_eq!(expected, caps.get_match());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: resolving capturing groups"] # [doc = ""] # [doc = " This example shows how to parse some simple dates and extract the"] # [doc = " components of each date via capturing groups."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{"] # [doc = "     nfa::thompson::pikevm::PikeVM,"] # [doc = "     util::captures::Captures,"] # [doc = " };"] # [doc = ""] # [doc = " let vm = PikeVM::new(r\"(?P<y>\\d{4})-(?P<m>\\d{2})-(?P<d>\\d{2})\")?;"] # [doc = " let mut cache = vm.create_cache();"] # [doc = ""] # [doc = " let haystack = \"2012-03-14, 2013-01-01 and 2014-07-05\";"] # [doc = " let all: Vec<Captures> = vm.captures_iter("] # [doc = "     &mut cache, haystack.as_bytes()"] # [doc = " ).collect();"] # [doc = " // There should be a total of 3 matches."] # [doc = " assert_eq!(3, all.len());"] # [doc = " // The year from the second match is '2013'."] # [doc = " let span = all[1].get_group_by_name(\"y\").unwrap();"] # [doc = " assert_eq!(\"2013\", &haystack[span]);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " This example shows that only the last match of a capturing group is"] # [doc = " reported, even if it had to match multiple times for an overall match"] # [doc = " to occur."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{nfa::thompson::pikevm::PikeVM, Span};"] # [doc = ""] # [doc = " let re = PikeVM::new(r\"([a-z]){4}\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = " let mut caps = re.create_captures();"] # [doc = ""] # [doc = " let haystack = b\"quux\";"] # [doc = " re.captures(&mut cache, haystack, &mut caps);"] # [doc = " assert!(caps.is_match());"] # [doc = " assert_eq!(Some(Span::from(3..4)), caps.get_group(1));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone)] pub struct NFA (Arc < Inner > ,) ;
    };
}

NFA!()